package edu.pe.cibertec.saibm.membresia.persistence;
import static org.assertj.core.api.Assertions.*; import java.time.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.autoconfigure.orm.jpa.*; import org.springframework.context.annotation.Import; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.test.context.DynamicPropertyRegistry; import org.springframework.test.context.DynamicPropertySource; import org.testcontainers.junit.jupiter.*; import org.testcontainers.postgresql.PostgreSQLContainer; import edu.pe.cibertec.saibm.membresia.application.port.in.*; import edu.pe.cibertec.saibm.membresia.infrastructure.config.*; import edu.pe.cibertec.saibm.membresia.infrastructure.persistence.*;
 @DataJpaTest(properties="spring.jpa.hibernate.ddl-auto=validate") @Testcontainers @Import({MembershipPersistenceAdapter.class,MembershipConfig.class}) class MembershipPostgresTest { @Container static final PostgreSQLContainer PG=new PostgreSQLContainer("postgres:16.9-alpine"); @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.datasource.url",PG::getJdbcUrl);r.add("spring.datasource.username",PG::getUsername);r.add("spring.datasource.password",PG::getPassword);} @Autowired JdbcTemplate sql; @Autowired @Qualifier("membership") MembershipUseCase use; @BeforeEach void clean(){sql.update("delete from membership_outbox");sql.update("delete from membership_history");sql.update("delete from membership_assignments");sql.update("delete from membership_plans");} @Test void assignmentPersistsSnapshotHistoryOutboxAndIdempotentReplay(){var p=use.createPlan(new MembershipUseCase.PlanCommand("gold","Gold",11,Instant.now().minusSeconds(1),null));var c=new MembershipUseCase.AssignmentCommand("u-1",p.id(),Instant.now(),null);var a=use.assign(c,"idem-1","corr-1");assertThat(use.assign(c,"idem-1","corr-1")).isEqualTo(a);assertThat(sql.queryForObject("select count(*) from membership_assignments",Integer.class)).isEqualTo(1);assertThat(sql.queryForObject("select reservation_limit from membership_assignments",Integer.class)).isEqualTo(11);assertThat(sql.queryForObject("select count(*) from membership_history",Integer.class)).isEqualTo(1);assertThat(sql.queryForObject("select count(*) from membership_outbox",Integer.class)).isEqualTo(2);assertThat(sql.queryForObject("select event_type from membership_outbox order by occurred_at limit 1",String.class)).isEqualTo("PlanUpdated.v1");} }
